fn walk_table_func<'a>(m: &'a protobuf::TableFunc, out: &mut dyn FnMut(NodeRef<'a>)) {
    for x in &m.ns_uris {
        visit_node(x, out);
    }
    for x in &m.ns_names {
        visit_node(x, out);
    }
    if let Some(x) = &m.docexpr {
        visit_node(x, out);
    }
    if let Some(x) = &m.rowexpr {
        visit_node(x, out);
    }
    for x in &m.colnames {
        visit_node(x, out);
    }
    for x in &m.coltypes {
        visit_node(x, out);
    }
    for x in &m.coltypmods {
        visit_node(x, out);
    }
    for x in &m.colcollations {
        visit_node(x, out);
    }
    for x in &m.colexprs {
        visit_node(x, out);
    }
    for x in &m.coldefexprs {
        visit_node(x, out);
    }
    for x in &m.colvalexprs {
        visit_node(x, out);
    }
    for x in &m.passingvalexprs {
        visit_node(x, out);
    }
    if let Some(x) = &m.plan {
        visit_node(x, out);
    }
}

