fn walk_query<'a>(m: &'a protobuf::Query, out: &mut dyn FnMut(NodeRef<'a>)) {
    if let Some(x) = &m.utility_stmt {
        visit_node(x, out);
    }
    for x in &m.cte_list {
        visit_node(x, out);
    }
    for x in &m.rtable {
        visit_node(x, out);
    }
    for x in &m.rteperminfos {
        visit_node(x, out);
    }
    if let Some(x) = &m.jointree {
        let x: &'a protobuf::FromExpr = x;
        out(NodeRef::FromExpr(x));
    }
    for x in &m.merge_action_list {
        visit_node(x, out);
    }
    if let Some(x) = &m.merge_join_condition {
        visit_node(x, out);
    }
    for x in &m.target_list {
        visit_node(x, out);
    }
    if let Some(x) = &m.on_conflict {
        let x: &'a protobuf::OnConflictExpr = x;
        out(NodeRef::OnConflictExpr(x));
    }
    for x in &m.returning_list {
        visit_node(x, out);
    }
    for x in &m.group_clause {
        visit_node(x, out);
    }
    for x in &m.grouping_sets {
        visit_node(x, out);
    }
    if let Some(x) = &m.having_qual {
        visit_node(x, out);
    }
    for x in &m.window_clause {
        visit_node(x, out);
    }
    for x in &m.distinct_clause {
        visit_node(x, out);
    }
    for x in &m.sort_clause {
        visit_node(x, out);
    }
    if let Some(x) = &m.limit_offset {
        visit_node(x, out);
    }
    if let Some(x) = &m.limit_count {
        visit_node(x, out);
    }
    for x in &m.row_marks {
        visit_node(x, out);
    }
    if let Some(x) = &m.set_operations {
        visit_node(x, out);
    }
    for x in &m.constraint_deps {
        visit_node(x, out);
    }
    for x in &m.with_check_options {
        visit_node(x, out);
    }
}

